505	    public BigDecimal retentionHeld(BigDecimal taxRate) {
506	        if (retentionReleasedOn != null) {
507	            return zero();
508	        }
509	        BigDecimal cleared = retentionCredited == null ? BigDecimal.ZERO : retentionCredited;
510	        return retention(taxRate).subtract(cleared).max(BigDecimal.ZERO).setScale(scale(), RoundingMode.HALF_UP);
