513	    /**
514	     * How a credit note of the amount comes off this invoice once the given amount has been paid, at
515	     * the tax rate: first what it still owes, then the retention it holds back. The part taken off in
516	     * all, and of that the part clearing retention; the rest is left over as credit.
517	     */
518	    public BigDecimal[] creditTaken(BigDecimal amount, BigDecimal paid, BigDecimal taxRate) {
519	        BigDecimal toDue = amount.min(amountDue(paid, taxRate).max(BigDecimal.ZERO));
520	        BigDecimal toRetention = amount.subtract(toDue).min(retentionHeld(taxRate));
521	        return new BigDecimal[] { toDue.add(toRetention), toRetention };
522	    }
