548	    /**
549	     * Works out the late interest charged by the given day at the annual rate (a percentage) from the
550	     * payments (those not reversed count), and keeps it as part of what is payable. A sent invoice not
551	     * spread over instalments, with something still owed more than {@link #GRACE_DAYS} days after its
552	     * due date, earns interest from its due date, compounded daily at rate / 365: a balance B owing for
553	     * d days earns B x ((1 + rate / 100 / 365)^d - 1), rounded half up to the cent. Each payment after
554	     * the due date ends a period; every period earns interest on what the invoice still owed during it
555	     * (earlier interest and retention left out), and a payment pays the interest earned so far first,
556	     * then the invoice.
557	     */
558	    public void accrueLateInterest(List<Payment> payments, BigDecimal taxRate, BigDecimal annualRate, LocalDate today) {
559	        this.lateInterest = BigDecimal.ZERO;
560	        if (status != InvoiceStatus.SENT || isCreditNote() || hasPlan() || dueDate == null || annualRate == null
561	                || annualRate.signum() <= 0 || !today.isAfter(dueDate.plusDays(GRACE_DAYS))) {
562	            return;
563	        }
564	        record Part(LocalDate on, Long paymentId, BigDecimal amount) {
565	        }
566	        List<Part> inOrder = payments.stream().filter(p -> !p.isReversed())
567	                .flatMap(p -> p.getAllocations().stream().filter(a -> a.getInvoiceId().equals(id))
568	                        .map(a -> new Part(a.getDate() == null ? p.getDate() : a.getDate(), p.getId(), a.getAmount())))
569	                .filter(p -> !p.on().isAfter(today))
570	                .sorted(Comparator.comparing(Part::on).thenComparing(Part::paymentId)).toList();
571	        BigDecimal owed = payableBeforeInterest(taxRate).subtract(retentionReleased(taxRate));
572	        BigDecimal paidInGrace = inOrder.stream().filter(p -> !p.on().isAfter(dueDate.plusDays(GRACE_DAYS)))
573	                .map(Part::amount).reduce(BigDecimal.ZERO, BigDecimal::add);
574	        if (owed.subtract(paidInGrace).signum() <= 0) {
575	            return;
576	        }
577	        BigDecimal daily = BigDecimal.ONE.add(annualRate.divide(BigDecimal.valueOf(36500), MathContext.DECIMAL128));
578	        BigDecimal charged = BigDecimal.ZERO;
579	        BigDecimal unpaidInterest = BigDecimal.ZERO;
580	        LocalDate from = dueDate;
581	        for (Part part : inOrder) {
582	            if (part.on().isAfter(dueDate) && owed.signum() > 0) {
583	                BigDecimal earned = interestOn(owed, daily, ChronoUnit.DAYS.between(from, part.on()));
584	                charged = charged.add(earned);
585	                unpaidInterest = unpaidInterest.add(earned);
586	                from = part.on();
587	            }
588	            BigDecimal toInterest = part.amount().min(unpaidInterest).max(BigDecimal.ZERO);
589	            unpaidInterest = unpaidInterest.subtract(toInterest);
590	            owed = owed.subtract(part.amount().subtract(toInterest));
591	        }
592	        if (owed.signum() > 0) {
593	            charged = charged.add(interestOn(owed, daily, ChronoUnit.DAYS.between(from, today)));
594	        }
595	        this.lateInterest = charged;
596	    }
597	
598	    /** The interest the balance earns over the days at the daily growth factor, rounded half up to the cent. */
599	    private BigDecimal interestOn(BigDecimal balance, BigDecimal daily, long days) {
600	        if (days <= 0) {
601	            return zero();
602	        }
603	        return balance.multiply(daily.pow((int) days, MathContext.DECIMAL128).subtract(BigDecimal.ONE))
604	                .setScale(scale(), RoundingMode.HALF_UP);
605	    }
