609	     * grand total, rounded down to the cent; nothing for a credit note, or an invoice holding back
610	     * retention or spread over instalments.
611	     */
612	    public BigDecimal earlyDiscount(BigDecimal taxRate) {
613	        if (isCreditNote() || hasPlan() || retentionPct.signum() > 0 || earlyPayDays == null
614	                || earlyPayPct == null || earlyPayPct.signum() <= 0) {
615	            return zero();
616	        }
617	        return total(taxRate).multiply(earlyPayPct).divide(BigDecimal.valueOf(100)).setScale(scale(), RoundingMode.DOWN);
618	    }
