634	        BigDecimal due = amountDue(paid, taxRate);
635	        if (!isEarlyWindowOpen(on, taxRate) || due.signum() <= 0) {
636	            return null;
637	        }
638	        return due.subtract(earlyDiscount(taxRate)).max(zero());
639	    }
