672	    /**
673	     * The plan's schedule at the tax rate, an ordinary loan of the grand total; empty when there is no
674	     * plan. With the monthly rate i (the annual rate / 12 / 100) the instalment is P x i / (1 - (1 +
675	     * i)^-n), or P / n at 0%, rounded half up to the cent. Each month's interest is the balance still
676	     * owed x i, rounded half up to the cent, and its principal the instalment less the interest; the
677	     * last instalment pays off the whole balance left plus its interest, so the schedule ends at zero.
678	     * Instalment k falls due k months after the issue date, on the same day (the month's last day when
679	     * it is shorter).
680	     */
681	    public List<Instalment> schedule(BigDecimal taxRate) {
682	        if (!hasPlan()) {
683	            return List.of();
684	        }
685	        MathContext mc = MathContext.DECIMAL128;
686	        BigDecimal principal = total(taxRate);
687	        BigDecimal i = instalmentRate.divide(BigDecimal.valueOf(1200), mc);
688	        int n = instalments;
689	        BigDecimal payment;
690	        if (i.signum() == 0) {
691	            payment = principal.divide(BigDecimal.valueOf(n), scale(), RoundingMode.HALF_UP);
692	        } else {
693	            BigDecimal growth = BigDecimal.ONE.add(i).pow(n, mc);
694	            payment = principal.multiply(i).multiply(growth)
695	                    .divide(growth.subtract(BigDecimal.ONE), mc).setScale(scale(), RoundingMode.HALF_UP);
696	        }
697	        List<Instalment> schedule = new ArrayList<>(n);
698	        BigDecimal balance = principal.setScale(scale(), RoundingMode.HALF_UP);
699	        for (int k = 1; k <= n; k++) {
700	            BigDecimal interest = balance.multiply(i).setScale(scale(), RoundingMode.HALF_UP);
701	            BigDecimal paid = k == n ? balance.add(interest) : payment;
702	            BigDecimal repaid = paid.subtract(interest);
703	            balance = balance.subtract(repaid);
704	            LocalDate due = issueDate == null ? null : issueDate.plusMonths(k);
705	            schedule.add(new Instalment(k, due, paid, interest, repaid, balance));
706	        }
707	        return schedule;
708	    }
709	
710	    /** The plan total at the tax rate: the sum of the instalments; null when there is no plan. */
711	    public BigDecimal planTotal(BigDecimal taxRate) {
712	        if (!hasPlan()) {
713	            return null;
714	        }
715	        return schedule(taxRate).stream().map(Instalment::payment).reduce(zero(), BigDecimal::add);
716	    }
717	
718	    /**
719	     * Each instalment of the plan at the tax rate once the given amount has been paid, on the given
720	     * day: payments (with what credit notes took off and anything written off) pay the instalments in
721	     * order, each paid off before the next. An instalment not paid off more than {@link #GRACE_DAYS}
722	     * days after its due date is overdue; empty when there is no plan.
723	     */
724	    public List<Instalment.Progress> instalmentProgress(BigDecimal paid, BigDecimal taxRate, LocalDate today) {
725	        List<Instalment.Progress> progress = new ArrayList<>();
726	        BigDecimal left = paid.add(getCredited()).add(writtenOff(paid, taxRate));
727	        for (Instalment instalment : schedule(taxRate)) {
728	            BigDecimal part = left.min(instalment.payment()).max(BigDecimal.ZERO).setScale(scale(), RoundingMode.HALF_UP);
729	            left = left.subtract(part);
730	            BigDecimal unpaid = instalment.payment().subtract(part);
731	            Instalment.Status status;
732	            if (unpaid.signum() <= 0) {
733	                status = Instalment.Status.PAID;
734	            } else if (instalment.dueDate() != null && today.isAfter(instalment.dueDate().plusDays(GRACE_DAYS))) {
735	                status = Instalment.Status.OVERDUE;
736	            } else if (part.signum() > 0) {
737	                status = Instalment.Status.PART_PAID;
738	            } else {
739	                status = Instalment.Status.DUE;
740	            }
741	            progress.add(new Instalment.Progress(instalment, part, unpaid, status));
742	        }
743	        return progress;
744	    }
745	
746	    /**
747	     * What is overdue at the tax rate once the given amount has been paid, on the given day: for a plan,
748	     * only what is unpaid on its overdue instalments; otherwise all that is due when it is overdue.
749	     */
750	    public BigDecimal overdueAmount(BigDecimal paid, BigDecimal taxRate, LocalDate today) {
751	        if (statusWhenPaid(paid, taxRate, today) != InvoiceStatus.OVERDUE) {
752	            return zero();
753	        }
754	        if (!hasPlan()) {
755	            return amountDue(paid, taxRate);
756	        }
757	        return instalmentProgress(paid, taxRate, today).stream()
758	                .filter(p -> p.status() == Instalment.Status.OVERDUE).map(Instalment.Progress::unpaid)
759	                .reduce(zero(), BigDecimal::add);
760	    }
761	
762	    /**
763	     * The due date as listed once the given amount has been paid: for a plan, the due date of its
764	     * next unpaid instalment (its own due date once all are paid); otherwise its own due date.
765	     */
766	    public LocalDate listedDueDate(BigDecimal paid, BigDecimal taxRate) {
767	        if (!hasPlan() || status != InvoiceStatus.SENT) {
768	            return dueDate;
769	        }
770	        return instalmentProgress(paid, taxRate, LocalDate.MIN).stream()
771	                .filter(p -> p.unpaid().signum() > 0).map(p -> p.instalment().dueDate())
772	                .findFirst().orElse(dueDate);
773	    }
774	
775	    /**
776	     * What is still unpaid on the earliest instalment not yet paid off, at the tax rate, once the
777	     * given amount has been paid; zero when there is no plan or all are paid.
778	     */
779	    public BigDecimal earliestUnpaid(BigDecimal paid, BigDecimal taxRate) {
780	        return instalmentProgress(paid, taxRate, LocalDate.MIN).stream()
781	                .map(Instalment.Progress::unpaid).filter(u -> u.signum() > 0)
782	                .findFirst().orElse(zero());
783	    }
784	
785	    public List<InvoiceLine> getLines() {
786	        return lines;
787	    }
788	
789	    /** Whether lines can still be added: only a draft is still being written. */
790	    public boolean isDraft() {
791	        return status == InvoiceStatus.DRAFT;
792	    }
793	
794	    /** Whether the invoice has been voided: it no longer counts, takes no payments and cannot be changed. */
795	    public boolean isVoid() {
796	        return status == InvoiceStatus.VOID;
797	    }
798	
799	    /** Voids a sent invoice. */
800	    public void markVoid() {
801	        this.status = InvoiceStatus.VOID;
802	    }
803	
804	    /** Whether the due date was set by hand; it is then kept when the invoice is sent. */
805	    public boolean isManualDueDate() {
806	        return manualDueDate;
807	    }
808	
809	    /**
810	     * Sets the due date by hand: not before the issue date nor more than {@link #MAX_DUE_DAYS} days
811	     * after it, or it is refused.
812	     */
813	    public void setDueDate(LocalDate dueDate) {
814	        if (issueDate != null && dueDate.isBefore(issueDate)) {
815	            throw new InvoiceRejectedException(
816	                    "The due date cannot be before the issue date (" + issueDate + ").");
817	        }
818	        if (issueDate != null && dueDate.isAfter(issueDate.plusDays(MAX_DUE_DAYS))) {
819	            throw new InvoiceRejectedException("The due date can be at most " + MAX_DUE_DAYS
820	                    + " days after the issue date, so no later than " + issueDate.plusDays(MAX_DUE_DAYS) + ".");
821	        }
822	        this.dueDate = dueDate;
823	        this.manualDueDate = true;
824	    }
825	
826	    /**
827	     * Marks the invoice sent, issued on the given date and due on the given date, unless its due date
828	     * was set by hand, which is kept.
829	     */
830	    public void markSent(LocalDate issueDate, LocalDate dueDate) {
831	        this.status = InvoiceStatus.SENT;
832	        this.issueDate = issueDate;
833	        if (!manualDueDate) {
834	            this.dueDate = dueDate;
835	        }
836	    }
837	
838	    /** Whether a due date set by hand is already past on the given send date. */
839	    public boolean dueDatePassedBy(LocalDate sendDate) {
840	        return manualDueDate && dueDate != null && dueDate.isBefore(sendDate);
841	    }
842	
843	    /** Puts a sent invoice back to draft, so it has to be sent again. */
844	    public void reopen() {
845	        this.status = InvoiceStatus.DRAFT;
846	    }
847	
848	    /** Days past its due date an invoice is given before it becomes overdue: a week's grace. */
849	    public static final int GRACE_DAYS = 7;
850	
851	    /**
852	     * The status on the given day once the given amount has been paid against the grand total at the
853	     * tax rate: a sent invoice with something still due more than {@link #GRACE_DAYS} days after its
854	     * due date is overdue, part paid or not. Held retention is never due, so never makes it overdue;
855	     * released retention is due {@link #RETENTION_DUE_DAYS} days after its release, and payments go to
856	     * the rest of the invoice before it. An invoice spread over instalments is instead overdue when any
857	     * of its instalments is (see {@link #instalmentProgress}).
858	     */
859	    public InvoiceStatus statusWhenPaid(BigDecimal paid, BigDecimal taxRate, LocalDate today) {
860	        return statusWhenPaid(paid, null, taxRate, today);
861	    }
862	
863	    /**
864	     * As {@link #statusWhenPaid(BigDecimal, BigDecimal, LocalDate)}, but a fully paid invoice whose
865	     * paid date (null when not known) is after its due date is paid late.
866	     */
867	    public InvoiceStatus statusWhenPaid(BigDecimal paid, LocalDate paidOn, BigDecimal taxRate, LocalDate today) {
868	        if (status != InvoiceStatus.SENT) {
869	            return status;
870	        }
871	        BigDecimal amountDue = amountDue(paid, taxRate);
872	        boolean due = amountDue.signum() > 0;
873	        BigDecimal retentionDue = amountDue.min(retentionReleased(taxRate)).max(BigDecimal.ZERO);
874	        boolean restDue = amountDue.subtract(retentionDue).signum() > 0;
875	        if (hasPlan()) {
876	            if (due && instalmentProgress(paid, taxRate, today).stream()
877	                    .anyMatch(p -> p.status() == Instalment.Status.OVERDUE)) {
878	                return InvoiceStatus.OVERDUE;
879	            }
880	        } else if (restDue && dueDate != null && today.isAfter(dueDate.plusDays(GRACE_DAYS))) {
881	            return InvoiceStatus.OVERDUE;
882	        }
883	        if (retentionDue.signum() > 0 && today.isAfter(retentionDueDate().plusDays(GRACE_DAYS))) {
884	            return InvoiceStatus.OVERDUE;
885	        }
886	        if (!due && retentionHeld(taxRate).signum() > 0) {
887	            return InvoiceStatus.RETENTION_HELD;
888	        }
889	        if (paid.signum() <= 0) {
890	            return !due && getCredited().signum() > 0 ? InvoiceStatus.CREDITED : status;
891	        }
892	        if (due) {
893	            return InvoiceStatus.PART_PAID;
894	        }
895	        return paidOn != null && dueDate != null && paidOn.isAfter(dueDate) ? InvoiceStatus.PAID_LATE
896	                : InvoiceStatus.PAID;
897	    }
898	
899	    /**
900	     * The date the invoice was fully paid: the date of the payment that cleared its grand total at the
901	     * tax rate, taking the parts of payments (not reversed) in the order they were applied (credit used
902	     * counts on the day it was applied); null while something is still due or retention is held.
903	     */
904	    public LocalDate paidOn(List<Payment> payments, BigDecimal taxRate) {
905	        BigDecimal total = payable(taxRate);
906	        if (status != InvoiceStatus.SENT || total.signum() <= 0 || retentionHeld(taxRate).signum() > 0) {
907	            return null;
908	        }
909	        record Part(LocalDate on, Long paymentId, BigDecimal amount) {
910	        }
911	        List<Part> inOrder = payments.stream().filter(p -> !p.isReversed())
912	                .flatMap(p -> p.getAllocations().stream().filter(a -> a.getInvoiceId().equals(id))
913	                        .map(a -> new Part(a.getDate() == null ? p.getDate() : a.getDate(), p.getId(), a.getAmount())))
914	                .sorted(Comparator.comparing(Part::on).thenComparing(Part::paymentId)).toList();
915	        BigDecimal sum = BigDecimal.ZERO;
916	        for (Part p : inOrder) {
917	            sum = sum.add(p.amount());
918	            if (sum.signum() > 0 && isSmallEnoughToWriteOff(total.subtract(sum))) {
919	                return p.on();
920	            }
921	        }
922	        return null;
923	    }
924	
925	    /**
926	     * What is still due once the given amount has been paid: the grand total less it, less what credit
927	     * notes have credited, less the retention still held, less anything written off — so nothing once
928	     * payments leave less than {@link #WRITE_OFF_LIMIT}. A credit note itself has nothing due.
929	     */
930	    public BigDecimal amountDue(BigDecimal paid, BigDecimal taxRate) {
931	        if (isCreditNote()) {
932	            return zero();
933	        }
934	        return payable(taxRate).subtract(paid).subtract(writtenOff(paid, taxRate));
935	    }
936	
937	    /**
938	     * What is written off once the given amount has been paid: when payments leave less than
939	     * {@link #WRITE_OFF_LIMIT} still due, all of what is left; otherwise nothing.
940	     */
941	    public BigDecimal writtenOff(BigDecimal paid, BigDecimal taxRate) {
942	        BigDecimal left = payable(taxRate).subtract(paid);
943	        return !isCreditNote() && paid.signum() > 0 && left.signum() > 0 && isSmallEnoughToWriteOff(left)
944	                ? left.setScale(scale(), RoundingMode.HALF_UP)
945	                : zero();
946	    }
947	
948	    /** The least a part payment may be at the tax rate: {@link #MINIMUM_PART_SHARE} of the grand total. */
949	    public BigDecimal minimumPart(BigDecimal taxRate) {
950	        return total(taxRate).multiply(MINIMUM_PART_SHARE).setScale(scale(), RoundingMode.HALF_UP);
951	    }
952	
953	    /**
954	     * Whether paying the amount on top of what was already paid is too small a part payment: under
955	     * {@link #minimumPart} while leaving something still due (what would be written off counts as settled).
956	     * For a plan the least is instead what is still unpaid on its earliest unpaid instalment.
957	     */
958	    public boolean isTooSmallPart(BigDecimal amount, BigDecimal paid, BigDecimal taxRate) {
959	        if (hasPlan()) {
960	            return amount.compareTo(earliestUnpaid(paid, taxRate)) < 0
961	                    && amountDue(paid.add(amount), taxRate).signum() > 0;
962	        }
963	        return amount.compareTo(minimumPart(taxRate)) < 0 && amountDue(paid.add(amount), taxRate).signum() > 0;
964	    }
965	
966	    /** Adds a line to the end of the invoice. */
967	    public void addLine(InvoiceLine line) {
968	        lines.add(line);
969	    }
970	
971	    /** Whether the invoice has the line with the given id. */
972	    public boolean hasLine(Long lineId) {
973	        return lines.stream().anyMatch(l -> lineId.equals(l.getId()));
974	    }
975	
976	    /**
977	     * Removes the line with the given id; whether the invoice had it. Refused when what is left would
978	     * be less than a fixed discount on the invoice.
979	     */
980	    public boolean removeLine(Long lineId) {
981	        InvoiceLine line = lines.stream().filter(l -> lineId.equals(l.getId())).findFirst().orElse(null);
982	        if (line == null) {
983	            return false;
984	        }
985	        BigDecimal left = subtotal().subtract(line.amount(scale()));
986	        if (discountAmount.signum() > 0 && left.compareTo(discountAmount) < 0) {
987	            throw new InvoiceRejectedException("This line cannot be removed: the "
988	                    + currency().format(left) + " left would be less than the "
989	                    + currency().format(discountAmount) + " discount.");
990	        }
991	        lines.remove(line);
992	        return true;
993	    }
994	
995	    /**
996	     * Changes the line with the given id to the given values; whether the invoice had it. Refused when
997	     * the subtotal would then be less than a fixed discount on the invoice.
998	     */
999	    public boolean updateLine(Long lineId, String description, BigDecimal qty, BigDecimal unitPrice,
1000	            boolean taxExempt, BigDecimal discountPct, BigDecimal taxRate) {
1001	        InvoiceLine line = lines.stream().filter(l -> lineId.equals(l.getId())).findFirst().orElse(null);
1002	        if (line == null) {
1003	            return false;
1004	        }
1005	        BigDecimal changed = new InvoiceLine(description, qty, unitPrice, taxExempt, discountPct, taxRate).amount(scale());
1006	        BigDecimal left = subtotal().subtract(line.amount(scale())).add(changed);
1007	        if (discountAmount.signum() > 0 && left.compareTo(discountAmount) < 0) {
1008	            throw new InvoiceRejectedException("This line cannot be changed: the "
1009	                    + currency().format(left) + " subtotal would be less than the "
1010	                    + currency().format(discountAmount) + " discount.");
1011	        }
1012	        line.update(description, qty, unitPrice, taxExempt, discountPct, taxRate);
1013	        return true;
1014	    }
1015	
1016	    /**
1017	     * The sum of the line amounts, each after its own discount and already to the cent — so the subtotal
1018	     * matches what a client gets by adding up the lines shown.
1019	     */
1020	    public BigDecimal subtotal() {
1021	        return lines.stream().map(l -> l.amount(scale()))
1022	                .reduce(zero(), BigDecimal::add);
1023	    }
1024	
1025	    /**
1026	     * The amount taken off: the fixed amount when there is one (never more than the subtotal, should
1027	     * lines have been changed since), otherwise the discount percentage of the subtotal, rounded down
1028	     * to the cent. When there is a cap, it limits everything taken off — the line discounts plus
1029	     * this — so this shrinks to what the line discounts leave under the cap, never below zero.
1030	     */
1031	    public BigDecimal discount() {
1032	        BigDecimal discount = discountAmount.signum() > 0
1033	                ? discountAmount.min(subtotal()).setScale(scale(), RoundingMode.HALF_UP)
1034	                : subtotal().multiply(discountPct).divide(BigDecimal.valueOf(100)).setScale(scale(), RoundingMode.DOWN);
1035	        if (discountCap == null) {
1036	            return discount;
1037	        }
1038	        BigDecimal lineDiscounts = lines.stream().map(l -> l.discount(scale()))
1039	                .reduce(zero(), BigDecimal::add);
1040	        BigDecimal left = discountCap.setScale(scale(), RoundingMode.HALF_UP).subtract(lineDiscounts).max(zero());
1041	        return discount.min(left);
1042	    }
1043	
1044	    /**
1045	     * Each line's share of the discount, in the order of the lines. The discount's cents are split in
1046	     * proportion to the line amounts: each line first gets the whole cents of its exact share
1047	     * (rounded down), then the cents left over go one each to the lines with the largest leftover
1048	     * fractions; between equal fractions the cent goes to the line with the larger amount, and between
1049	     * equal amounts too to the lower line id. The shares add up to the discount.
1050	     */
1051	    public List<BigDecimal> discountShares() {
1052	        BigInteger discountCents = discount().movePointRight(scale()).toBigIntegerExact();
1053	        BigInteger subtotalCents = subtotal().movePointRight(scale()).toBigIntegerExact();
1054	        int n = lines.size();
1055	        BigInteger[] shares = new BigInteger[n];
1056	        BigInteger[] leftovers = new BigInteger[n];
1057	        BigInteger given = BigInteger.ZERO;
1058	        for (int i = 0; i < n; i++) {
1059	            if (subtotalCents.signum() == 0) {
1060	                shares[i] = BigInteger.ZERO;
1061	                leftovers[i] = BigInteger.ZERO;
1062	            } else {
1063	                // The exact share is discount * amount / subtotal; all fractions share the subtotal
1064	                // as denominator, so the remainders compare as the fractions do.
1065	                BigInteger[] qr = discountCents.multiply(lines.get(i).amount(scale()).movePointRight(scale()).toBigIntegerExact())
1066	                        .divideAndRemainder(subtotalCents);
1067	                shares[i] = qr[0];
1068	                leftovers[i] = qr[1];
1069	            }
1070	            given = given.add(shares[i]);
1071	        }
1072	        List<Integer> order = new ArrayList<>();
1073	        for (int i = 0; i < n; i++) {
1074	            order.add(i);
1075	        }
1076	        order.sort(Comparator.<Integer, BigInteger>comparing(i -> leftovers[i]).reversed()
1077	                .thenComparing(Comparator.<Integer, BigDecimal>comparing(i -> lines.get(i).amount(scale())).reversed())
1078	                .thenComparing(i -> lines.get(i).getId(), Comparator.nullsLast(Comparator.naturalOrder())));
1079	        int left = discountCents.subtract(given).intValueExact();
1080	        for (int k = 0; k < left; k++) {
1081	            int i = order.get(k);
1082	            shares[i] = shares[i].add(BigInteger.ONE);
1083	        }
1084	        List<BigDecimal> result = new ArrayList<>(n);
1085	        for (BigInteger share : shares) {
1086	            result.add(new BigDecimal(share, scale()));
1087	        }
1088	        return result;
1089	    }
1090	
1091	    /**
1092	     * Each line's tax, in the order of the lines: the line's own rate (a percentage), or the given
1093	     * workspace rate when it has none, on the line's amount less its share of the discount, rounded
1094	     * half up to the cent. Tax-exempt lines, and every line of a tax-exempt client, have no tax.
1095	     */
1096	    public List<BigDecimal> lineTaxes(BigDecimal taxRate) {
1097	        List<BigDecimal> shares = discountShares();
1098	        List<BigDecimal> taxes = new ArrayList<>(lines.size());
1099	        for (int i = 0; i < lines.size(); i++) {
1100	            InvoiceLine line = lines.get(i);
1101	            taxes.add(clientTaxExempt || line.isTaxExempt() ? zero()
1102	                    : line.amount(scale()).subtract(shares.get(i)).multiply(line.taxRate(taxRate)).divide(BigDecimal.valueOf(100))
1103	                            .setScale(scale(), RoundingMode.HALF_UP));
1104	        }
1105	        return taxes;
1106	    }
1107	
1108	    /** The tax charged at the given rate (a percentage): the sum of the line taxes. */
1109	    public BigDecimal tax(BigDecimal taxRate) {
1110	        return lineTaxes(taxRate).stream().reduce(zero(), BigDecimal::add);
1111	    }
1112	
1113	    /** The grand total: the subtotal less the discount, plus tax at the given rate. */
1114	    public BigDecimal total(BigDecimal taxRate) {
1115	        return subtotal().subtract(discount()).add(tax(taxRate));
1116	    }
1117	}
